// Local time rendering
// ----------------------------------------------------------------------------

const TIME_FORMAT = { hour: "numeric", minute: "2-digit" }
const SHORT_DATE_FORMAT = { month: "short", day: "numeric" }
const DATE_FORMAT = { month: "short", day: "numeric", year: "numeric" }
const LONG_DATE_FORMAT = { weekday: "long", month: "long", day: "numeric" }
const NUMERIC_DATE_TIME_FORMAT = { month: "numeric", day: "numeric", year: "2-digit", hour: "numeric", minute: "2-digit" }
const DATE_TIME_FORMAT = { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" }

const formatters = {}

function formatter(name, options) {
  if (!formatters[name]) {
    formatters[name] = new Intl.DateTimeFormat("en-US", options)
  }
  return formatters[name]
}

function formatWith(options, date) {
  return normalizeSpacing(formatter(JSON.stringify(options), options).format(date))
}

function normalizeSpacing(string) {
  return string.replace(/\u202f/g, " ")
}

function relativeTime(date, amount, unit = "day") {
  return normalizeSpacing(new Intl.RelativeTimeFormat("en-US", { numeric: "auto" }).format(amount, unit))
}

export function beginningOfLocalDay(date) {
  return new Date(date.getFullYear(), date.getMonth(), date.getDate())
}

export function signedLocalDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfLocalDay(toDate) - beginningOfLocalDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function formatLocalTime(date, format = "relative", now = new Date()) {
  if (!(date instanceof Date) || isNaN(date)) return ""

  switch (format) {
    case "time":
      return formatWith(TIME_FORMAT, date)
    case "date":
      return formatWith(DATE_FORMAT, date)
    case "short_date":
      return formatWith(SHORT_DATE_FORMAT, date)
    case "long_date":
      return formatWith(LONG_DATE_FORMAT, date)
    case "date_time":
      return formatWith(DATE_TIME_FORMAT, date)
    case "numeric_date_time":
      return formatWith(NUMERIC_DATE_TIME_FORMAT, date)
    case "day":
      return formatDay(date, now)
    case "time_ago":
    case "ago":
      return formatTimeAgo(date, now)
    case "relative":
    case "time_or_date":
    case "future":
    default:
      return formatRelative(date, now)
  }
}

function formatDay(date, now) {
  const difference = signedLocalDifferenceInDays(now, date)

  if (difference === 0) return relativeTime(date, 0, "day") // "today"
  if (difference === -1) return relativeTime(date, -1, "day") // "yesterday"
  if (difference === 1) return relativeTime(date, 1, "day") // "tomorrow"

  if (Math.abs(difference) < 7) {
    return formatWith({ weekday: "long" }, date)
  }

  return formatWith(SHORT_DATE_FORMAT, date)
}

function formatRelative(date, now) {
  const difference = signedLocalDifferenceInDays(now, date)

  if (difference === 0) return formatWith(TIME_FORMAT, date)
  if (difference === -1) return relativeTime(date, -1, "day") // "yesterday"
  if (difference === 1) return relativeTime(date, 1, "day") // "tomorrow"

  if (Math.abs(difference) < 7) {
    return relativeTime(date, difference, "day")
  }

  return formatWith(SHORT_DATE_FORMAT, date)
}

function formatTimeAgo(date, now) {
  const seconds = Math.round((now - date) / 1000)

  if (seconds < 45) return "just now"

  const minutes = Math.round(seconds / 60)
  if (minutes < 60) return relativeTime(date, -minutes, "minute")

  const hours = Math.round(seconds / 3600)
  if (hours < 24) return relativeTime(date, -hours, "hour")

  const difference = signedLocalDifferenceInDays(now, date)
  if (difference > -7) return relativeTime(date, difference, "day")

  return formatWith(SHORT_DATE_FORMAT, date)
}
